def serialize_chain(chain: EvidenceChain) -> str | None:
    """
    Serialize EvidenceChain to JSON string for storage in payload_text/envelope.

    Returns None if serialization fails OR if result exceeds MAX_CHAIN_JSON_BYTES.
    """
    if chain.is_empty:
        return None
    try:
        import orjson
        raw = orjson.dumps(_chain_to_dict(chain))
    except Exception:
        try:
            raw = _msgspec_encode(_chain_to_dict(chain))
        except Exception:
            logger.warning('[EVIDENCE_CHAIN] serialize failed')
            return None
    if len(raw) > MAX_CHAIN_JSON_BYTES:
        logger.warning('[EVIDENCE_CHAIN] chain size %d exceeds MAX_CHAIN_JSON_BYTES %d', len(raw), MAX_CHAIN_JSON_BYTES)
        return None
    try:
        return raw.decode('utf-8')
    except Exception:
        return None

def serialize_envelope(envelope: FindingEnvelope) -> str | None:
    """
    Serialize FindingEnvelope to JSON string for storage in payload_text.

    Returns None if serialization fails OR if result exceeds MAX_ENVELOPE_SIZE.
    Fail-soft: caller degrades to plain finding when None is returned.
    """
    if not envelope.is_populated():
        return None
    try:
        import orjson
        raw = orjson.dumps({'audit_reason': envelope.audit_reason, 'evidence_pointers': envelope.evidence_pointers, 'signal_facets': envelope.signal_facets, 'suggested_pivots': envelope.suggested_pivots, 'chain_refs': envelope.chain_refs})
    except Exception:
        try:
            raw = _msgspec_encode(envelope.__dict__)
        except Exception:
            logger.warning('[ENVELOPE] serialize failed — will degrade to plain finding')
            return None
    if len(raw) > MAX_ENVELOPE_SIZE:
        logger.warning('[ENVELOPE] envelope size %d exceeds MAX_ENVELOPE_SIZE %d — will degrade to plain finding', len(raw), MAX_ENVELOPE_SIZE)
        return None
    try:
        return raw.decode('utf-8')
    except Exception:
        return None

