def put(self, prefix: str, key: bytes, value: bytes) -> bool:
    """Put a single key-value pair."""
    if self._closed:
        return False
    try:
        self._ensure_init()
        with self._env.begin(write=True) as txn:
            txn.put(self._key(prefix, key), value)
        return True
    except Exception as exc:
        logger.debug(f"[LMDB-UNIFIED] put failed: {exc}")
        return False

def get(self, prefix: str, key: bytes) -> bytes | None:
    """Get a value by key."""
    if self._closed:
        return None
    try:
        self._ensure_init()
        with self._env.begin() as txn:
            return txn.get(self._key(prefix, key))
    except Exception:
        return None

def delete(self, prefix: str, key: bytes | str) -> bool:
    """Delete a key from the store."""
    if self._closed:
        return False
    try:
        self._ensure_init()
        with self._env.begin(write=True) as txn:
            txn.delete(self._key(prefix, key))
        return True
    except Exception as exc:
        logger.debug(f"[LMDB-UNIFIED] delete failed: {exc}")
        return False

def get_str(self, prefix: str, key: str) -> dict | None:
    """Get a JSON-deserialized value by string key (WALManager compatibility)."""
    if self._closed:
        return None
    try:
        self._ensure_init()
        import orjson
        with self._env.begin(buffers=True) as txn:
            raw = txn.get(self._key_str(prefix, key))
        if raw is None:
            return None
        # orjson.loads accepts memoryview directly — zero-copy
        return _msgspec_loads(raw)
    except Exception:
        return None

def putmany_str(
    self, prefix: str, items: list[tuple[str, dict]]
) -> list[bool]:
    """Batch put with string keys. Returns per-item success list."""
    if self._closed or not items:
        return [False] * len(items) if items else []
    try:
        self._ensure_init()
        # M1-OPT: Single write transaction per chunk via putmulti_bounded_str
        from hledac.universal.utils.lmdb_bulk import putmulti_bounded_str
        return putmulti_bounded_str(self._env, items, key_prefix=prefix)
    except Exception as exc:
        logger.debug(f"[LMDB-UNIFIED] putmany_str failed: {exc}")
        return [False] * len(items)

def iter_prefix(self, prefix: str) -> list[tuple[bytes, bytes]]:
    """Iterate all items with given prefix."""
    results: list[tuple[bytes, bytes]] = []
    if self._closed:
        return results
    try:
        self._ensure_init()
        prefixed_key = prefix.encode() + b":"
        with self._env.begin() as txn:
            cursor = txn.cursor()
            for key, value in cursor:
                if key.startswith(prefixed_key):
                    original_key = key[len(prefixed_key):]
                    results.append((original_key, value))
    except Exception as exc:
        logger.debug(f"[LMDB-UNIFIED] iter_prefix failed: {exc}")
    return results

def close(self) -> None:
    """Close the LMDB environment."""
    if self._closed:
        return
    if self._env is not None:
        try:
            self._env.close()
        except Exception as exc:
            logger.debug(f"[LMDB-UNIFIED] close error: {exc}")
        self._env = None
    self._closed = True
    self._initialized = False

def _extract_url_from_provenance(self, provenance: tuple[str, ...]) -> str:
    """Extract the first HTTP(S) URL from a provenance tuple.

    Handles two formats:
    - Raw URL: "https://example.com"
    - Tagged URL: "url:https://example.com" (PUBLIC lane format from _build_public_finding)
    """
    if not provenance:
        return ""
    for item in provenance:
        if not isinstance(item, str):
            continue
        # Raw URL format
        if item.startswith("http"):
            return item
        # Tagged URL format: "url:https://..."
        if item.startswith("url:"):
            url = item[4:]  # Strip "url:" prefix
            if url.startswith("http"):
                return url
    return ""

if url_fingerprint:
    fingerprint = url_fingerprint
    entropy = 0.0  # not meaningful when URL is identity
else:
    text = finding.payload_text if finding.payload_text else finding.query
    if not text or not text.strip():
        text = finding.query
    normalized = _normalize_for_quality(text)
    entropy = _compute_entropy(normalized)
    fingerprint = _compute_dedup_fingerprint(normalized)

if len(fingerprint) < _QUALITY_MIN_ENTROPY_LEN:
    # Sprint-F265B P2: High-confidence IoC bypass — hex hashes skip semantic dedup
    # Sprint F265D: Feed sources also skip semantic dedup
    text_for_embed = url_from_provenance or (finding.payload_text or finding.query)
    is_high_conf_ioc = (
        text_for_embed is not None
        and _HIGH_CONF_IOC_RE.match(text_for_embed.strip()) is not None
    )
    if self._semantic_dedup_cache is not None and not is_high_conf_ioc and not is_feed_source:
        try:
            if text_for_embed and len(text_for_embed) >= 16:
                is_dup = self._semantic_dedup_cache.check_and_cache(  # type: ignore[attr-defined]
                    text_for_embed, threshold=0.75  # Sprint-F265B: was 0.80, too tight for IOC data (caused 100% rejection in sprint 300s)
                )
                if is_dup:
                    self._state._quality_duplicate_count += 1
                    _logger.debug(
                        "[QUALITY] short_string semantic_dup hit fp=%s url=%s",
                        fingerprint[:16],
                        (url_from_provenance or "")[:80],
                    )
                    return self._make_decision(
                        accepted=False,
                        reason="semantic_duplicate",
                        entropy=entropy,
                        fingerprint=fingerprint,
                        duplicate=True,
                    )
        except Exception as e:
            _logger.warning(f"Quality gate error (short_string path): {e}")
    # Short string + no semantic duplicate → store and accept
    if self._lmdb_store_fn is not None:
        self._lmdb_store_fn(fingerprint, finding.finding_id)
    self._state.add_to_hot_cache(fingerprint, finding.finding_id)
    return self._make_decision(
        accepted=True,
        reason="short_string_skip",
        entropy=entropy,
        fingerprint=fingerprint,
        duplicate=False,
    )

if (
    self._semantic_dedup_cache is not None
    and not is_high_conf_ioc
    and not is_feed_source
):
    _dedup_cache = self._semantic_dedup_cache
    assert _dedup_cache is not None
    try:
        text_for_embed = url_from_provenance or (finding.payload_text or finding.query)
        if text_for_embed and len(text_for_embed) >= 16:
            is_dup = _dedup_cache.check_and_cache(  # type: ignore[attr-defined]
                text_for_embed, threshold=0.75  # Sprint-F265B: was 0.80, too tight for IOC data (caused 100% rejection in sprint 300s)
            )
            if is_dup:
                self._state._quality_duplicate_count += 1
                _logger.debug(
                    "[QUALITY] semantic_dup hit fp=%s url=%s",
                    fingerprint[:16],
                    (url_from_provenance or "")[:80],
                )
                return self._make_decision(
                    accepted=False,
                    reason="semantic_duplicate",
                    entropy=entropy,
                    fingerprint=fingerprint,
                    duplicate=True,
                )
    except Exception as e:
        _logger.warning(f"Quality gate error (entropy path): {e}")

for idx, f in enumerate(findings):
    url = self._state._extract_url_from_provenance(f.provenance) if f.provenance else ''
    if url:
        url_fingerprints[idx] = url
        url_indices.append(idx)
        texts.append('')
    else:
        payload_text = f.payload_text if f.payload_text else f.query
        if not (payload_text and payload_text.strip()):
            payload_text = f.query
        texts.append(payload_text)
        payload_indices.append(idx)

if url_indices:
    url_texts = [url_fingerprints[i] for i in url_indices]
    batch_urls = self._rust_batch_str(
        url_texts,
        batch_fn=lambda lst: _rust_backend.quality.batch_url_fingerprints(lst),
        single_fn=lambda s: _rust_backend.quality.url_fingerprint(s),
        py_fn=_compute_url_fingerprint,
    )
    for j, idx in enumerate(url_indices):
        url_fingerprints[idx] = batch_urls[j]

def _rust_batch_str(
    self,
    items: list[str],
    batch_fn: collections.abc.Callable[[list[str]], list[str]],
    single_fn: collections.abc.Callable[[str], str],
    py_fn: collections.abc.Callable[[str], str],
) -> list[str]:
    """Rust batch → single-item fallback → Python fallback for str results."""
    if not items:
        return []
    try:
        return batch_fn(items)
    except Exception:
        pass
    try:
        return [single_fn(item) for item in items]
    except Exception:
        return [py_fn(item) for item in items]

def _rust_batch_float(
    self,
    items: list[str],
    batch_fn: collections.abc.Callable[[list[str]], list[float]],
    single_fn: collections.abc.Callable[[str], float],
    py_fn: collections.abc.Callable[[str], float],
) -> list[float]:
    """Rust batch → single-item fallback → Python fallback for float results."""
    if not items:
        return []
    try:
        return batch_fn(items)
    except Exception:
        pass
    try:
        return [single_fn(item) for item in items]
    except Exception:
        return [py_fn(item) for item in items]

